//! What the generator writes one output file into, and how that file names a type: by its path
//! in the same file, by `proto.wkt` for a well-known type, or through the module of another
//! generated file. Each output records the names it uses, so its imports list exactly those.
const std = @import("std");
const Features = @import("features.zig").Features;
const Allocator = std.mem.Allocator;
const names = @import("names.zig");
const index_file = @import("index.zig");
const Index = index_file.Index;

pub const Error = index_file.Error || error{NameCollision};

pub const Out = struct {
    arena: Allocator,
    bytes: std.ArrayList(u8) = .empty,
    index: *const Index,
    /// The .proto file whose declarations this output holds.
    file: []const u8,
    /// The features of the fields being written: the file's, then each enclosing message's.
    features: Features,
    /// The modules of other generated files this output names.
    used_modules: std.StringArrayHashMapUnmanaged(void) = .empty,
    /// Whether the output declares a service, which names `connect.Method`.
    uses_connect: bool = false,
    /// Whether the output declares a table of rules, which names `protovalidate.Rules`
    /// (decision 47).
    uses_protovalidate: bool = false,
    /// Each repeated type the file uses, as its `proto.Repeated(...)` call, and the name the
    /// file declares it under.
    repeated_types: std.StringArrayHashMapUnmanaged([]const u8) = .empty,
    /// The names a repeated type must not take: the file's own types and services, and the names
    /// already given to repeated types.
    taken_names: std.StringHashMapUnmanaged(void) = .empty,

    pub fn print(out: *Out, comptime format: []const u8, args: anytype) Allocator.Error!void {
        try out.bytes.print(out.arena, format, args);
    }

    pub fn indent(out: *Out, depth: usize) Allocator.Error!void {
        for (0..depth) |_| try out.bytes.appendSlice(out.arena, "    ");
    }

    /// The Zig expression this output names the type `type_name` with.
    pub fn reference(out: *Out, type_name: []const u8) Error![]const u8 {
        if (index_file.wkt_reference(type_name)) |short| return std.fmt.allocPrint(out.arena, "proto.wkt.{s}", .{short});
        const entry = try out.index.get(type_name);
        if (std.mem.eql(u8, entry.file, out.file)) {
            return entry.zig_path;
        }
        const module = try names.import_name(out.arena, entry.file);
        try out.used_modules.put(out.arena, module, {});
        return std.fmt.allocPrint(out.arena, "{s}.{s}", .{ module, entry.zig_path });
    }

    /// Marks `name` as one the file declares, so that no repeated type takes it.
    pub fn reserve(out: *Out, name: []const u8) Allocator.Error!void {
        try out.taken_names.put(out.arena, name, {});
    }

    /// The name a field uses for the repeated type `call`. Zig counts every function call in a
    /// struct's field types against one branch quota of 1,000, and nothing inside the struct can
    /// raise it. So the file declares each repeated type once, under `name`, and each field uses
    /// that name. If `name` is taken, the type gets the first free one of `name2`, `name3` and
    /// so on.
    pub fn repeated(out: *Out, call: []const u8, name: []const u8) Allocator.Error![]const u8 {
        const entry = try out.repeated_types.getOrPut(out.arena, call);
        if (!entry.found_existing) entry.value_ptr.* = try out.free_name(name);
        return entry.value_ptr.*;
    }

    fn free_name(out: *Out, name: []const u8) Allocator.Error![]const u8 {
        var candidate = name;
        var number: usize = 1;
        // At most `count` names are taken, so one of the first `count + 1` candidates is free.
        for (0..out.taken_names.count() + 1) |_| {
            if (!out.taken_names.contains(candidate)) break;
            number += 1;
            candidate = try std.fmt.allocPrint(out.arena, "{s}{d}", .{ name, number });
        }
        std.debug.assert(!out.taken_names.contains(candidate));
        try out.taken_names.put(out.arena, candidate, {});
        return candidate;
    }

    /// The file's text: its header, the imports its body uses, then the body.
    pub fn assemble(out: *const Out) Allocator.Error![]const u8 {
        var text: std.ArrayList(u8) = .empty;
        const arena = out.arena;
        try text.print(arena, "//! Code generated by protoc-gen-connect-zig. DO NOT EDIT.\n//! source: {s}\n", .{out.file});
        try text.print(arena, "//! The build gives this file the modules protobuf{s}{s}", .{
            if (out.uses_connect) ", connect" else "",
            if (out.uses_protovalidate) ", protovalidate" else "",
        });
        for (out.used_modules.keys()) |module| try text.print(arena, ", {s}", .{module});
        try text.appendSlice(arena, ".\n");
        try text.appendSlice(arena, "const proto = @import(\"protobuf\");\n");
        if (out.uses_connect) try text.appendSlice(arena, "const connect = @import(\"connect\");\n");
        if (out.uses_protovalidate) try text.appendSlice(arena, "const validate = @import(\"protovalidate\");\n");
        for (out.used_modules.keys()) |module| try text.print(arena, "const {s} = @import(\"{s}\");\n", .{ module, module });
        try out.write_repeated(&text);
        try text.appendSlice(arena, out.bytes.items);
        return text.items;
    }

    /// Declares each repeated type the file uses, once, after the imports.
    fn write_repeated(out: *const Out, text: *std.ArrayList(u8)) Allocator.Error!void {
        if (out.repeated_types.count() == 0) return;
        const arena = out.arena;
        try text.appendSlice(arena,
            \\
            \\// Each repeated field's type, declared once. Zig counts every function call in a struct's
            \\// field types against one branch quota, so a message with more than about 1,000 repeated
            \\// fields would not compile if each field called `proto.Repeated` itself.
            \\
        );
        var calls = out.repeated_types.iterator();
        while (calls.next()) |entry| try text.print(arena, "const {s} = {s};\n", .{ entry.value_ptr.*, entry.key_ptr.* });
    }
};

/// A Zig name without its `@"..."` quoting.
pub fn unescaped(name: []const u8) []const u8 {
    const quote = "@\"";
    if (std.mem.startsWith(u8, name, quote)) return name[quote.len .. name.len - 1];
    return name;
}

pub fn full_name(arena: Allocator, scope: []const u8, name: []const u8) Allocator.Error![]const u8 {
    if (scope.len == 0) return name;
    return std.fmt.allocPrint(arena, "{s}.{s}", .{ scope, name });
}
